from collections import deque

def min_knight_moves(x, y):
    dirs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]
    q = deque([(0, 0, 0)])  # (x, y, moves)
    visited = {(0, 0)}

    while q:
        cx, cy, moves = q.popleft()
        if (cx, cy) == (x, y):
            return moves

        for dx, dy in dirs:
            nx, ny = cx + dx, cy + dy
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny, moves + 1))

    return -1
